import{_ as a,a as e,p as s,o as i}from"./index-CVmwAqS1.js";const o={},n={class:"spec-content"};function r(d,t){return i(),e("div",n,[...t[0]||(t[0]=[s('<h1 data-v-26356324>Architecture</h1><p class="lead" data-v-26356324>Entgl is a peer-to-peer mesh platform. EntglDb, its flagship service, provides leaderless database synchronization for local-first applications.</p><section data-v-26356324><h2 data-v-26356324>Platform Architecture</h2><p data-v-26356324>Entgl is structured in two layers: a reusable <strong data-v-26356324>mesh infrastructure</strong> and the <strong data-v-26356324>services</strong> built on top of it.</p><div class="flow-diagram" data-v-26356324><div class="step" data-v-26356324><div style="margin-bottom:8px;color:var(--accent-secondary);font-weight:600;" data-v-26356324>Mesh Infrastructure</div> Auto-Discovery • Encrypted Transport • Gossip Protocol • Leader Election • Peer Management </div><div class="step" style="margin-top:12px;" data-v-26356324><div style="margin-bottom:8px;color:var(--accent-primary);font-weight:600;" data-v-26356324>Services (built on the mesh)</div> EntglDb Sync (v2.1 — stable) • File Sync (planned) • Messaging (planned) </div></div></section><section data-v-26356324><h2 data-v-26356324>Design Philosophy</h2><ul data-v-26356324><li data-v-26356324><strong data-v-26356324>Local First:</strong> Reads and writes happen locally on the device, ensuring zero-latency and offline availability.</li><li data-v-26356324><strong data-v-26356324>Peer-to-Peer:</strong> No central server. Every node is equal. The mesh is self-organizing and self-healing.</li><li data-v-26356324><strong data-v-26356324>Eventually Consistent:</strong> Data converges across the cluster using Conflict-Free Replicated Data Types (CRDT) principles.</li><li data-v-26356324><strong data-v-26356324>Platform, not Product:</strong> The mesh infrastructure (discovery, transport, gossip) is independent from database sync. New services can be built on the same network.</li></ul></section><section data-v-26356324><h2 data-v-26356324>Hybrid Logical Clock (HLC)</h2><p data-v-26356324>To order events without a central authority, EntglDb uses Hybrid Logical Clocks. This combines physical time with a logical counter to capture causality.</p><div class="alert-box" data-v-26356324><strong data-v-26356324>Last Write Wins (LWW)</strong><p data-v-26356324>By default, conflicts are resolved by comparing HLC timestamps. The higher timestamp wins.</p></div></section><section data-v-26356324><h2 data-v-26356324>Synchronization</h2><p data-v-26356324>Sync happens in two stages:</p><ol data-v-26356324><li data-v-26356324><strong data-v-26356324>Discovery:</strong> Nodes find each other on the LAN via UDP Multicast.</li><li data-v-26356324><strong data-v-26356324>Anti-Entropy:</strong> Nodes pair up via TCP and exchange Merkle Trees (or High Water Marks) to identify missing data.</li></ol><h3 data-v-26356324>Gossip Protocol</h3><p data-v-26356324>Updates propagate via an epidemic algorithm. When a node changes data, it pushes it to random connected peers, who in turn push it to others.</p></section><section data-v-26356324><h2 data-v-26356324>Data Flow</h2><div class="flow-diagram" data-v-26356324><div class="step" data-v-26356324>App Write ➤ Local Store ➤ OpLog (hash-chained) ➤ Sync Orchestrator ➤ TCP Push ➤ Remote Peer</div></div></section>',7)])])}const l=a(o,[["render",r],["__scopeId","data-v-26356324"]]);export{l as default};
